//! What every generated table shares.

/// The header of a generated file: the summary, then the marker the lint recognises.
pub fn header(summary: &str, generator: &str) -> String {
    format!(
        "//! {summary}\n//!\n//! @generated by `cargo xtask gen` ({generator}); do not edit by hand.\n\n"
    )
}

/// A Rust string literal.
pub fn string(text: &str) -> String {
    serde_json::to_string(text).unwrap_or_default()
}

/// An `f32` as the shortest decimal that reads back as the reference's bits.
pub fn f32_from_bits(hex: &str) -> Result<String, String> {
    let bits = u32::from_str_radix(hex, 16).map_err(|error| format!("{hex}: {error}"))?;
    let text = format!("{:?}", f32::from_bits(bits));
    Ok(text)
}

/// An `f32` given as its bits, as the shortest decimal that reads back as the same bits. A value
/// that is not finite has no literal.
pub fn f32_literal(bits: u32) -> Result<String, String> {
    let value = f32::from_bits(bits);
    if value.is_finite() {
        Ok(format!("{value:?}"))
    } else {
        Err(format!("{bits:08x} is not a finite float"))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_float_is_written_as_the_shortest_decimal_of_its_bits() {
        assert_eq!(f32_from_bits("3e99999a").as_deref(), Ok("0.3"));
        assert_eq!(f32_from_bits("3f800000").as_deref(), Ok("1.0"));
        assert!(f32_from_bits("zz").is_err());
    }

    #[test]
    fn the_header_carries_the_marker_the_lint_knows() {
        assert!(header("A table.", "x").contains("@generated by `cargo xtask gen` (x)"));
    }
}
